"use client";

import { Bell, Menu, Mic, Send } from "lucide-react";
import { useRouter } from "next/navigation";
import { useState } from "react";
import PageShell from "../components/PageShell";
import { Chip, PurpleButton } from "../components/ui";

type Message = {
  role: "user" | "ai";
  content: string;
};

const needChips = ["交通", "行程安排", "住宿", "會議用品"];

export default function DashboardPage() {
  const router = useRouter();
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [showChips, setShowChips] = useState(false);
  const [selectedNeeds, setSelectedNeeds] = useState<string[]>([]);

  function handleSend() {
    const text = input.trim();
    if (!text) return;
    setMessages((prev) => [
      ...prev,
      { role: "user", content: text },
      { role: "ai", content: "好的！你的主要需求是？（可複選）" },
    ]);
    setInput("");
    setShowChips(true);
  }

  function toggleNeed(need: string) {
    setSelectedNeeds((prev) =>
      prev.includes(need) ? prev.filter((n) => n !== need) : [...prev, need],
    );
  }

  const hasStarted = messages.length > 0;

  return (
    <PageShell>
      <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 bg-white">
        <Menu size={20} className="text-gray-500" />
        <p className="font-semibold text-gray-900">首頁</p>
        <div className="flex items-center gap-3">
          <div className="relative">
            <Bell size={20} className="text-gray-500" />
            <span className="absolute -top-0.5 -right-0.5 w-2 h-2 rounded-full bg-red-500" />
          </div>
          <div className="w-7 h-7 rounded-full bg-violet-200 text-violet-700 text-xs font-semibold flex items-center justify-center">
            J
          </div>
        </div>
      </div>

      <div className="flex-1 px-5 py-5 space-y-4">
        {!hasStarted && (
          <div className="space-y-1">
            <p className="text-xl font-bold text-gray-900">早安, Jamie ☀️</p>
            <p className="text-sm text-gray-400">今天想完成什麼事呢？</p>
          </div>
        )}

        {messages.map((m, i) => (
          <div
            key={i}
            className={`flex ${m.role === "user" ? "justify-end" : "justify-start"}`}
          >
            <div
              className={`max-w-[75%] rounded-2xl px-4 py-2.5 text-sm leading-relaxed ${
                m.role === "user"
                  ? "bg-violet-600 text-white rounded-br-sm"
                  : "bg-gray-100 text-gray-800 rounded-bl-sm"
              }`}
            >
              {m.content}
            </div>
          </div>
        ))}

        {showChips && (
          <div className="flex flex-wrap gap-2">
            {needChips.map((need) => (
              <Chip
                key={need}
                active={selectedNeeds.includes(need)}
                onClick={() => toggleNeed(need)}
              >
                {need}
              </Chip>
            ))}
          </div>
        )}
      </div>

      <div className="p-4 border-t border-gray-100 bg-white space-y-3">
        {selectedNeeds.length > 0 && (
          <PurpleButton onClick={() => router.push("/task-result")}>
            產生任務計畫
          </PurpleButton>
        )}

        {!hasStarted && (
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setInput("我下週要去東京出差，一個人")}
              className="text-xs rounded-full bg-gray-100 text-gray-500 px-3 py-1.5 hover:bg-gray-200"
            >
              💡 我下週要去東京出差
            </button>
          </div>
        )}

        <div className="flex items-center gap-2 rounded-2xl bg-gray-100 px-4 py-3">
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSend()}
            placeholder="用自然語言告訴我你想做什麼..."
            className="flex-1 bg-transparent text-sm outline-none placeholder:text-gray-400"
          />
          {input ? (
            <button onClick={handleSend} className="text-violet-600">
              <Send size={18} />
            </button>
          ) : (
            <Mic size={18} className="text-gray-400" />
          )}
        </div>
      </div>
    </PageShell>
  );
}
