import Link from "next/link";
import type { ReactNode } from "react";

export function PurpleButton({
  children,
  href,
  onClick,
  type = "button",
  variant = "solid",
  className = "",
}: {
  children: ReactNode;
  href?: string;
  onClick?: () => void;
  type?: "button" | "submit";
  variant?: "solid" | "outline";
  className?: string;
}) {
  const base =
    "w-full rounded-2xl py-3.5 text-center font-medium transition active:scale-[0.98]";
  const style =
    variant === "solid"
      ? "bg-violet-600 text-white hover:bg-violet-700"
      : "border-2 border-violet-600 text-violet-600 hover:bg-violet-50";

  if (href) {
    return (
      <Link href={href} className={`${base} ${style} ${className}`}>
        {children}
      </Link>
    );
  }
  return (
    <button type={type} onClick={onClick} className={`${base} ${style} ${className}`}>
      {children}
    </button>
  );
}

export function Chip({
  children,
  active = false,
  onClick,
}: {
  children: ReactNode;
  active?: boolean;
  onClick?: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-full px-4 py-2 text-sm font-medium transition ${
        active
          ? "bg-violet-600 text-white"
          : "bg-violet-100 text-violet-700 hover:bg-violet-200"
      }`}
    >
      {children}
    </button>
  );
}

export function ScreenHeader({
  title,
  subtitle,
  left,
  right,
}: {
  title: string;
  subtitle?: string;
  left?: ReactNode;
  right?: ReactNode;
}) {
  return (
    <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 bg-white">
      <div className="w-8">{left}</div>
      <div className="flex-1 text-center">
        <p className="font-semibold text-gray-900">{title}</p>
        {subtitle && <p className="text-xs text-gray-400">{subtitle}</p>}
      </div>
      <div className="w-8 flex justify-end">{right}</div>
    </div>
  );
}
